using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace BlockchainContract
{
    public class AuthToken
    {
        public string ServiceId { get; set; }
        public byte[] Signature { get; set; }
        public long Timestamp { get; set; }
        public Dictionary<string, string> Claims { get; set; }
    }

    public class ServiceRegistry
    {
        private readonly Dictionary<string, byte[]> _trustedKeys;
        private readonly Dictionary<string, AuthToken> _sessionCache;

        public ServiceRegistry()
        {
            _trustedKeys = new Dictionary<string, byte[]>();
            _sessionCache = new Dictionary<string, AuthToken>();
        }

        public void RegisterService(string serviceId, byte[] publicKey)
        {
            if (string.IsNullOrEmpty(serviceId) || publicKey == null || publicKey.Length == 0)
                throw new ArgumentException("Invalid registration parameters");
            _trustedKeys[serviceId] = publicKey;
        }

        public AuthToken ResolveSession(string sessionKey)
        {
            _sessionCache.TryGetValue(sessionKey ?? string.Empty, out AuthToken token);
            return token;
        }

        public void CacheSession(string sessionKey, AuthToken token)
        {
            if (sessionKey != null && token != null)
                _sessionCache[sessionKey] = token;
        }

        public byte[] GetPublicKey(string serviceId)
        {
            _trustedKeys.TryGetValue(serviceId ?? string.Empty, out byte[] key);
            return key;
        }
    }

    public class CrossServiceAuthenticator
    {
        private readonly ServiceRegistry _registry;
        private readonly long _maxClockSkew;

        public CrossServiceAuthenticator(ServiceRegistry registry, long maxClockSkewSeconds = 300)
        {
            _registry = registry ?? throw new ArgumentNullException(nameof(registry));
            _maxClockSkew = maxClockSkewSeconds;
        }

        public AuthToken ValidateAndExtract(string sessionKey, string expectedServiceId)
        {
            AuthToken cached = _registry.ResolveSession(sessionKey);

            if (cached != null && cached.ServiceId == expectedServiceId)
            {
                if (IsTimestampValid(cached.Timestamp))
                    return cached;
                else
                    return null;
            }

            return null;
        }

        private bool IsTimestampValid(long timestamp)
        {
            long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            return Math.Abs(now - timestamp) <= _maxClockSkew;
        }
    }

    public class SmartContractState
    {
        public string Owner { get; set; }
        public Dictionary<string, long> Balances { get; set; }
        public Dictionary<string, string> Metadata { get; set; }

        public SmartContractState()
        {
            Balances = new Dictionary<string, long>();
            Metadata = new Dictionary<string, string>();
        }
    }

    public class BlockchainSmartContract
    {
        private readonly SmartContractState _state;
        private readonly CrossServiceAuthenticator _authenticator;
        private readonly ServiceRegistry _registry;

        public BlockchainSmartContract(ServiceRegistry registry)
        {
            _registry = registry ?? throw new ArgumentNullException(nameof(registry));
            _authenticator = new CrossServiceAuthenticator(registry);
            _state = new SmartContractState { Owner = "genesis" };
        }

        public bool ExecuteTransfer(string sessionKey, string fromService, string toAddress, long amount)
        {
            if (amount <= 0)
                return false;

            // Validate destination address before any transfer logic.
            if (string.IsNullOrEmpty(toAddress))
                return false;

            AuthToken authToken = ResolveAuthChain(sessionKey, fromService);

            string delegatedAuthority = ExtractDelegatedAuthority(authToken);

            if (!ValidateDelegationChain(delegatedAuthority, fromService))
                return false;

            return PerformTransfer(delegatedAuthority, toAddress, amount);
        }

        private AuthToken ResolveAuthChain(string sessionKey, string serviceId)
        {
            AuthToken primary = _authenticator.ValidateAndExtract(sessionKey, serviceId);

            if (primary != null)
                return primary;

            AuthToken fallback = AttemptFallbackResolution(sessionKey, serviceId);
            return fallback;
        }

        private AuthToken AttemptFallbackResolution(string sessionKey, string serviceId)
        {
            byte[] serviceKey = _registry.GetPublicKey(serviceId);

            if (serviceKey != null && serviceKey.Length >= 32)
            {
                string derivedSession = DeriveSessionFromKey(serviceKey, sessionKey);
                return _authenticator.ValidateAndExtract(derivedSession, serviceId);
            }

            return null;
        }

        private string ExtractDelegatedAuthority(AuthToken token)
        {
            if (token?.Claims == null)
                return null;

            token.Claims.TryGetValue("delegated_authority", out string authority);
            return authority;
        }

        private bool ValidateDelegationChain(string authority, string expectedService)
        {
            if (string.IsNullOrEmpty(authority))
                return false;

            string[] chain = authority.Split(':');

            if (chain.Length < 2 || string.IsNullOrEmpty(chain[1]))
                return false;

            return chain[0].Equals(expectedService, StringComparison.OrdinalIgnoreCase);
        }

        private bool PerformTransfer(string authority, string toAddress, long amount)
        {
            string sourceAccount = ResolveAccountFromAuthority(authority);

            if (string.IsNullOrEmpty(sourceAccount))
                return false;

            // Guard the destination account here as well (defense in depth).
            if (string.IsNullOrEmpty(toAddress))
                return false;

            long currentBalance = GetBalance(sourceAccount);
            if (currentBalance < amount)
                return false;

            long destinationBalance = GetBalance(toAddress);
            long newDestinationBalance;
            try
            {
                // Prevent silent integer overflow when crediting the destination.
                newDestinationBalance = checked(destinationBalance + amount);
            }
            catch (OverflowException)
            {
                return false;
            }

            _state.Balances[sourceAccount] = currentBalance - amount;
            _state.Balances[toAddress] = newDestinationBalance;
            return true;
        }

        private string ResolveAccountFromAuthority(string authority)
        {
            string[] parts = authority.Split(':');
            return parts.Length > 1 ? parts[1] : null;
        }

        private long GetBalance(string account)
        {
            if (string.IsNullOrEmpty(account))
                return 0;
            _state.Balances.TryGetValue(account, out long balance);
            return balance;
        }

        private string DeriveSessionFromKey(byte[] key, string sessionKey)
        {
            using (var hmac = new HMACSHA256(key))
            {
                byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(sessionKey ?? string.Empty));
                return Convert.ToBase64String(hash);
            }
        }

        public void SetBalance(string account, long amount)
        {
            if (!string.IsNullOrEmpty(account) && amount >= 0)
                _state.Balances[account] = amount;
        }

        public long GetPublicBalance(string account)
        {
            if (string.IsNullOrEmpty(account))
                return 0;
            return GetBalance(account);
        }
    }
}
